export const RemotionRoot = () => (
  <>
    <Composition id="LogoIntro" {...intro} defaultProps={{ dark: false, ...claim }} />
    <Composition id="LogoIntroDark" {...intro} defaultProps={{ dark: true, ...claim }} />
  </>
);

