  { label: "Stack", dur: 150, Comp: StackScene },
];

const starts = SCENES.reduce<number[]>((acc, s, i) => [...acc, i === 0 ? 0 : acc[i - 1] + SCENES[i - 1].dur - OVERLAP], []);
