      <div style={{ display: "flex", alignItems: "center", gap: 18 }}>
        <span style={{ fontSize: 22, fontWeight: 700, color: C.muted }}>{SCENES[Math.max(1, current)].label}</span>
        <div style={{ display: "flex", gap: 6 }}>
          {SCENES.slice(1).map((s, i) => (
            <span
              key={s.label}
              style={{ width: 40, height: 6, borderRadius: 3, background: i + 1 <= current ? C.ink : C.line }}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

export const TechStack = () => (
  <AbsoluteFill
    style={{
      background: `radial-gradient(ellipse at 50% 45%, #ffffff 0%, ${C.paper} 70%)`,
