"use client";
/**
 * Load animation on first open and every reload (the root layout persists across client
 * navigation, so it does not replay between pages). Same choreography as the Remotion
 * logo intro (video/src/LogoIntro.tsx), condensed to about two seconds:
 * the bars slide in along their axis and meet like a baton handover, the overlap only
 * appears where they touch, then the wordmark unfolds and the page fades in.
 *
 * Rendered on the server at t = 0 (bars hidden), so the page never flashes before it.
 */
import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { animate, AnimatePresence, motion, useReducedMotion } from "motion/react";

const TOTAL = 1.9; // seconds until the overlay starts fading
const SLIDE = 70; // start distance in viewBox units
const ANGLE = (35 * Math.PI) / 180;
const AXIS = { x: Math.cos(ANGLE), y: -Math.sin(ANGLE) };

const clamp01 = (v: number) => Math.min(1, Math.max(0, v));
const easeOut = (v: number) => 1 - Math.pow(1 - clamp01(v), 3);
const span = (t: number, start: number, len: number) => easeOut((t - start) / len);
const bar = (cx: number, cy: number, d: number) => `translate(${AXIS.x * d} ${AXIS.y * d}) rotate(-35 ${cx} ${cy})`;

export function Splash() {
  const reduce = useReducedMotion();
  const [t, setT] = useState(0);
  const [done, setDone] = useState(false);
  const wordRef = useRef<HTMLSpanElement>(null);
  const [wordWidth, setWordWidth] = useState(0);

  // Measure the wordmark so the lockup recenters exactly; again once Manrope is loaded.
  useLayoutEffect(() => {
    const measure = () => setWordWidth(wordRef.current?.offsetWidth ?? 0);
    measure();
    document.fonts?.ready.then(measure);
  }, []);

  useEffect(() => {
    if (reduce) {
      setT(TOTAL);
      const id = setTimeout(() => setDone(true), 400);
      return () => clearTimeout(id);
    }
    const controls = animate(0, TOTAL, {
      duration: TOTAL,
      ease: "linear",
      onUpdate: setT,
      onComplete: () => setDone(true),
    });
    return () => controls.stop();
  }, [reduce]);

  const teal = span(t, 0.05, 0.55);
  const coral = span(t, 0.18, 0.55);
  const tealShift = -SLIDE * (1 - teal);
  const coralShift = SLIDE * (1 - coral);
  const bump = 1 + 0.06 * Math.sin(Math.PI * clamp01((t - 0.62) / 0.3));
  const ring = (start: number) => {
    const p = clamp01((t - start) / 0.7);
    return { r: 10 + easeOut(p) * 46, opacity: p > 0 && p < 1 ? (1 - p) * 0.45 : 0, w: 1.6 * (1 - p) };
  };
  const ringA = ring(0.66);
  const ringB = ring(0.8);
  const reveal = span(t, 0.95, 0.6);

  return (
    <AnimatePresence>
      {!done && (
        <motion.div
          className="splash"
          aria-hidden="true"
          exit={{ opacity: 0, filter: "blur(6px)" }}
          transition={{ duration: 0.45, ease: "easeOut" }}
        >
          <div className="splash-lockup">
            <svg
              className="splash-mark"
              viewBox="0 0 64 64"
              style={{ transform: `scale(${bump})` }}
            >
              <defs>
                <clipPath id="splash-clip">
                  <rect x={4} y={26} width={38} height={14} rx={7} transform={bar(23, 33, tealShift)} />
                </clipPath>
              </defs>
              <circle cx={32} cy={32} r={ringA.r} fill="none" stroke="#0F8B8D" strokeWidth={ringA.w} opacity={ringA.opacity} />
              <circle cx={32} cy={32} r={ringB.r} fill="none" stroke="#FF7A59" strokeWidth={ringB.w} opacity={ringB.opacity} />
              <rect x={4} y={26} width={38} height={14} rx={7} fill="#0F8B8D" opacity={clamp01(teal * 2)} transform={bar(23, 33, tealShift)} />
              <rect x={22} y={24} width={38} height={14} rx={7} fill="#FF7A59" opacity={clamp01(coral * 2)} transform={bar(41, 31, coralShift)} />
              {/* Clip on an untransformed group; on the rect it would inherit the rect's transform. */}
              <g clipPath="url(#splash-clip)">
                <rect x={22} y={24} width={38} height={14} rx={7} fill="var(--ink)" transform={bar(41, 31, coralShift)} />
              </g>
            </svg>
            <div className="splash-word" style={{ width: wordWidth * reveal, marginLeft: 16 * reveal }}>
              <span ref={wordRef}>
                {"stafette".split("").map((ch, i) => {
                  const p = span(t, 1.05 + i * 0.06, 0.35);
                  return (
                    <span
                      key={i}
                      style={{ opacity: p, transform: `translateY(${(1 - p) * 10}px)`, filter: `blur(${(1 - p) * 4}px)` }}
                    >
                      {ch}
                    </span>
                  );
                })}
              </span>
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

